SELECT id, session_id, event_type, page, event_time, duration_sec, COUNT(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_duration_sec, AVG(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_duration_sec, MAX(duration_sec) OVER (PARTITION BY page, session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_duration_sec, SUM(duration_sec) OVER (ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS duration_sec_sum_7d FROM web_events WHERE TO_DATE(event_time) < '2025-08-01'
